rtl:
always_comb begin
  next_state = state;
  case (state)
    S0: if (go)   next_state = S1;
    S1: if (done) next_state = S2;
    S2:           next_state = S0;
    // States 3-7 unhandled — FSM freezes on illegal entry
  endcase
end

fix_replacement:
always_comb begin
  next_state = state;
  case (state)
    S0: if (go)   next_state = S1;
    S1: if (done) next_state = S2;
    S2:           next_state = S0;
    default:      next_state = S0;  // Recover any illegal state
  endcase
end
